#include "MemoryTestAssessmentJson.h"
#include "MemoryClockCheckJson.h"
#include "MemoryLibraryInput.h"
#include <iostream>
#include <stdexcept>
namespace {
using namespace dft::memory;size_t assertions=0;
void need(bool ok,const char *reason){++assertions;if(!ok)throw std::runtime_error(reason);}
std::string json(const MemoryTestAssessmentReport &r){hier::protocol::JsonWriter w;writeMemoryTestAssessment(w,r);return w.str();}
void relations(const MemoryTestAssessmentReport &r){const auto &a=r.assessment;need(a.rows.size()==r.source.coverage.rows.size(),"one row per macro");need(a.rows.size()==a.satisfiedInstances+a.blockedInstances+a.pendingInstances,"count conservation");for(size_t i=0;i<a.rows.size();++i){need(a.rows[i].macro==i,"macro/coverage identity");if(a.rows[i].clockCheck){const auto memory=r.domains.rows[r.check.rows[*a.rows[i].clockCheck].row].memory;need(r.source.coverage.rows[i].memory==memory,"same investigation mapping index");}}}
}
int main()try {
 const auto dir=std::filesystem::path(DFT_MEMORY_ASSESSMENT_DIR);auto lib=loadMemoryLibrary(dir/"memory-clock-library.json");need(bool(lib),"library");
 MemoryTestAssessmentRequest q;auto &request=q.test.schedule.test;request.investigation.scope="domain_resolved";request.investigation.recursive=true;request.investigation.mapping.models=lib->models;for(const auto &m:lib->models)request.planning.profiles.push_back({m.definitionName,2,10});q.test.schedule.rules=std::vector<MemoryTestRule>{{{"domain_resolved"},true,"D",""}};q.test.timing.clocks={{"D",1000}};q.test.timing.policy.waveOverheadPicoseconds=7;
 q.expectations={{"D",{{"domain_resolved.clk",0,"posedge"},{"domain_resolved.clk",1,"posedge"},{"domain_resolved.clk",0,"negedge"}}}};
 hier::model::OpenOptions opts;opts.tops={"domain_resolved"};opts.files={dir/"memory-clock-sources.sv",dir/"memory-test-domains.sv"};auto design=hier::Design::open(opts);need(design&&design.value()->diagnostics(100).errorCount==0,"real design");
 auto good=assessMemoryTests(*design.value(),q);need(good&&good->assessment.complete&&good->assessment.verdict=="pass"&&good->assessment.satisfiedInstances==6,"all six satisfied");need(good->source.source.timeline.durationPicoseconds==32014,"two waves of sixteen cycles at 1000ps plus two 7ps barriers");relations(*good);
 auto old=inspectMemoryTestCoverage(*design.value(),q.test);hier::protocol::JsonWriter a,b;writeMemoryTestCoverage(a,*old);writeMemoryTestCoverage(b,good->source);need(a.str()==b.str(),"exact original coverage");
 auto x=q;x.expectations[0].sources.resize(1);auto fail=assessMemoryTests(*design.value(),x);need(fail&&fail->assessment.complete&&fail->assessment.verdict=="fail"&&fail->assessment.blockedInstances==2&&fail->assessment.satisfiedInstances==4,"complete timing with known bit and edge violations");relations(*fail);
 x.test.schedule.test.planning.limits.maxWork=1;fail=assessMemoryTests(*design.value(),x);need(fail&&!fail->assessment.complete&&fail->assessment.verdict=="fail"&&fail->assessment.blockedInstances==2&&fail->assessment.pendingInstances==3&&fail->assessment.satisfiedInstances==1,"known violations survive planning prefix");
 x=q;x.test.schedule.test.planning.policy.maxPowerMicrowatts=1;fail=assessMemoryTests(*design.value(),x);need(fail&&fail->assessment.blockedInstances==6&&fail->check.matchedInstances==6,"planning defects survive source matches");x.expectations[0].sources.resize(1);fail=assessMemoryTests(*design.value(),x);size_t both=0;for(const auto &row:fail->assessment.rows)both+=row.issues==std::vector<std::string>{"test_blocked","clock_mismatch"};need(both==2&&fail->assessment.blockedInstances==6,"both causes retained without double counting");
 x=q;x.test.schedule.scheduling.policy.maxPowerMicrowatts=1;fail=assessMemoryTests(*design.value(),x);need(fail&&fail->assessment.blockedInstances==6,"schedule power block");
 x=q;x.test.timing.clocks.clear();fail=assessMemoryTests(*design.value(),x);need(fail&&fail->assessment.blockedInstances==4&&fail->assessment.pendingInstances==2&&fail->assessment.verdict=="fail","missing period blocks responsible entry, not entire wave");
 x=q;x.test.timing.limits.maxWork=1;auto partial=assessMemoryTests(*design.value(),x);need(partial&&partial->assessment.pendingInstances==6&&partial->assessment.verdict=="unknown","uncommitted wave is pending");
 x=q;x.test.schedule.test.investigation.mapping.limits.maxMacros=2;partial=assessMemoryTests(*design.value(),x);need(partial&&partial->assessment.rows.size()==6&&partial->assessment.satisfiedInstances==2&&partial->assessment.pendingInstances==4,"mapping prefix retains observed macros");need(partial->assessment.rows[2].issues==std::vector<std::string>{"test_pending","clock_check_not_reached"}&&!partial->assessment.rows[2].clockCheck,"not reached is not a mismatch");relations(*partial);
 x=q;x.clockLimits.maxWork=1;partial=assessMemoryTests(*design.value(),x);need(partial&&partial->assessment.pendingInstances==6&&partial->assessment.verdict=="unknown","clock prefix cannot pass");
 x=q;x.expectations.clear();partial=assessMemoryTests(*design.value(),x);need(partial&&partial->assessment.pendingInstances==6&&partial->assessment.rows[0].issues==std::vector<std::string>{"clock_unconstrained"},"no inferred constraints");
 x=q;x.test.schedule.rules.reset();partial=assessMemoryTests(*design.value(),x);need(partial&&partial->assessment.blockedInstances==6&&partial->assessment.rows[0].issues==std::vector<std::string>{"test_blocked","domain_missing"},"no inferred assignments");
 x=q;x.expectations.push_back({"unused",{{"missing",0,"posedge"}}});partial=assessMemoryTests(*design.value(),x);need(partial&&partial->assessment.satisfiedInstances==6&&partial->assessment.verdict=="unknown","satisfied prefix with unused declaration cannot pass");
 x=q;x.test.schedule.test.investigation.recursive=false;partial=assessMemoryTests(*design.value(),x);need(partial&&partial->assessment.rows.empty()&&partial->assessment.verdict=="unknown","empty with unchecked declaration");x.expectations.clear();partial=assessMemoryTests(*design.value(),x);need(partial&&partial->assessment.complete&&partial->assessment.verdict=="pass","empty complete");
 for(int kind=0;kind<5;++kind){x=q;x.test.schedule.test.investigation.scope="absent";switch(kind){case 0:x.test.timing.limits.maxWork=0;break;case 1:x.clockLimits.maxDepth=0;break;case 2:x.expectations[0].sources[0].edge="both";break;case 3:x.test.schedule.scheduling.policy.maxParallelControllers=0;break;default:x.test.schedule.test.planning.policy.maxParallelMemories=0;break;}auto bad=assessMemoryTests(*design.value(),x);need(!bad&&bad.error().code==hier::ErrorCode::BadRequest,"validate every stage before lookup");}
 std::stop_source stop;stop.request_stop();auto cancelled=assessMemoryTests(*design.value(),x,stop.get_token());need(!cancelled&&cancelled.error().code==hier::ErrorCode::Cancelled,"pre-cancel priority");
 const auto encoded=json(*good);design.value().reset();q={};need(encoded==json(*good),"owned after design/request release");std::cout<<assertions<<" memory assessment assertions passed\n";return 0;
}catch(const std::exception &e){std::cerr<<e.what()<<'\n';return 1;}
